import{_ as n,C as o,o as e,c as d,a7 as t,b as s,w as r,a as l,E as u,a8 as E}from"./chunks/framework.BCbKzsgW.js";const _=JSON.parse('{"title":"事件驱动与异步任务","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/task-scheduling/triggers/event-driven.md","filePath":"development/common/task-scheduling/triggers/event-driven.md","lastUpdated":1793441194000}'),c={name:"development/common/task-scheduling/triggers/event-driven.md"};function h(p,a,A,B,m,b){const i=o("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="shi-jian-qu-dong-yu-yi-bu-ren-wu" tabindex="-1">事件驱动与异步任务 <a class="header-anchor" href="#shi-jian-qu-dong-yu-yi-bu-ren-wu" aria-label="Permalink to &quot;事件驱动与异步任务&quot;">​</a></h1><p>事件记录已经发生的业务事实，任务表达希望执行的动作。例如 <code>VideoUploaded</code> 表示视频已经上传完成，<code>TranscodeVideo</code> 表示需要转码。一个事件可以产生多个任务，也可以在判断条件后不产生任务。</p><p>异步执行把后续处理交给独立的 Worker。它减少请求等待时间，但请求成功通常只意味着业务与任务已被接受，不意味着转码、通知等动作已经完成。</p><h2 id="yi-ci-ye-wu-bian-hua-ru-he-chan-sheng-ren-wu" tabindex="-1">一次业务变化如何产生任务 <a class="header-anchor" href="#yi-ci-ye-wu-bian-hua-ru-he-chan-sheng-ren-wu" aria-label="Permalink to &quot;一次业务变化如何产生任务&quot;">​</a></h2><p>以视频上传为例：</p><table tabindex="0"><thead><tr><th>阶段</th><th>需要确认的事实</th></tr></thead><tbody><tr><td>完成上传</td><td>文件已经可读，业务记录指向确定的对象版本</td></tr><tr><td>保存事件</td><td>事件 ID、视频 ID 和版本已持久化</td></tr><tr><td>订阅事件</td><td>转码服务接收 <code>VideoUploaded</code></td></tr><tr><td>创建任务</td><td>保存目标格式、源文件版本和业务键</td></tr><tr><td>执行转码</td><td>Worker 检查对象仍存在并生成结果</td></tr><tr><td>发布结果</td><td>记录产物版本，使正确结果对用户可见</td></tr></tbody></table><p>对象存储与业务数据库可能分别提交。上表以“文件已完成上传并校验”为起点；上传后未登记的孤立对象，需要另行清理或核对。</p><h2 id="shu-ju-ku-ti-jiao-yu-shi-jian-fa-bu" tabindex="-1">数据库提交与事件发布 <a class="header-anchor" href="#shu-ju-ku-ti-jiao-yu-shi-jian-fa-bu" aria-label="Permalink to &quot;数据库提交与事件发布&quot;">​</a></h2><p>先提交业务再发布事件，存在“业务已保存，进程却在发布前崩溃”的窗口。先发布事件再提交业务，则可能让消费者处理最终回滚的变化。</p><p>事务发件箱（Transactional Outbox）把业务记录与待发事件写入同一个数据库事务，独立的投递器再发布事件。下面是依据 <a href="https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html" target="_blank" rel="noreferrer">AWS Outbox 模式说明</a>整理的流程：</p>',10)),(e(),s(E,null,{default:r(()=>[u(i,{id:"mermaid-89",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20B%20as%20%E4%B8%9A%E5%8A%A1%E6%9C%8D%E5%8A%A1%0A%20%20%20%20participant%20D%20as%20%E6%95%B0%E6%8D%AE%E5%BA%93%0A%20%20%20%20participant%20R%20as%20%E6%8A%95%E9%80%92%E5%99%A8%0A%20%20%20%20participant%20Q%20as%20%E6%B6%88%E6%81%AF%E4%BB%A3%E7%90%86%0A%20%20%20%20participant%20W%20as%20%E6%B6%88%E8%B4%B9%E8%80%85%0A%20%20%20%20B-%3E%3ED%3A%20%E5%90%8C%E4%B8%80%E4%BA%8B%E5%8A%A1%E4%BF%9D%E5%AD%98%E4%B8%9A%E5%8A%A1%E4%B8%8E%20Outbox%0A%20%20%20%20D--%3E%3EB%3A%20%E6%8F%90%E4%BA%A4%E6%88%90%E5%8A%9F%0A%20%20%20%20R-%3E%3ED%3A%20%E8%AF%BB%E5%8F%96%E5%BE%85%E5%8F%91%E4%BA%8B%E4%BB%B6%0A%20%20%20%20R-%3E%3EQ%3A%20%E5%8F%91%E5%B8%83%E4%BA%8B%E4%BB%B6%0A%20%20%20%20Q--%3E%3ER%3A%20%E5%8F%91%E5%B8%83%E7%A1%AE%E8%AE%A4%0A%20%20%20%20R-%3E%3ED%3A%20%E6%A0%87%E8%AE%B0%E5%B7%B2%E5%8F%91%E5%B8%83%0A%20%20%20%20Q-%3E%3EW%3A%20%E5%88%86%E5%8F%91%E4%BA%8B%E4%BB%B6%0A%20%20%20%20W-%3E%3EW%3A%20%E5%B9%82%E7%AD%89%E5%A4%84%E7%90%86%0A%20%20%20%20W--%3E%3EQ%3A%20%E6%B6%88%E8%B4%B9%E7%A1%AE%E8%AE%A4%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>数据库提交与事件落表可以原子完成，投递器发布与标记已发布仍是两个动作。投递器可能重复发送，因此消费者仍要去重。</p><h2 id="que-ren-fa-sheng-zai-na-yi-ceng" tabindex="-1">确认发生在哪一层 <a class="header-anchor" href="#que-ren-fa-sheng-zai-na-yi-ceng" aria-label="Permalink to &quot;确认发生在哪一层&quot;">​</a></h2><p>发布确认说明消息代理按自身配置接受了消息；消费确认说明消费者声明这一投递已经处理。RabbitMQ 官方文档说明这两类确认彼此独立，见<a href="https://www.rabbitmq.com/docs/confirms" target="_blank" rel="noreferrer">发布确认与消费确认</a>。</p><p>消费者先确认再提交业务，崩溃后可能缺失处理；先提交业务再确认，崩溃后可能收到重复消息。对于需要恢复的业务，通常采用后者，并把业务更新与去重记录放进同一事务。</p><p>如果消费者只是创建一个持久化任务，消费确认可以放在任务提交之后。后续任务是否完成，由任务系统记录，不能在这里混为一个确认。</p><h2 id="chong-fuluan-xu-yu-jiu-shi-jian" tabindex="-1">重复、乱序与旧事件 <a class="header-anchor" href="#chong-fuluan-xu-yu-jiu-shi-jian" aria-label="Permalink to &quot;重复、乱序与旧事件&quot;">​</a></h2><ul><li>事件 ID 用来识别同一条事实的重复投递。</li><li>业务键用来识别同一个动作，例如某视频某版本的某种输出格式。</li><li>业务版本用来识别已经被新状态取代的旧事件。</li></ul><p>这些字段承担不同职责。仅靠随机任务 ID，无法判断两个不同事件是否要求同一个业务动作。</p><p>库存提醒还需要明确是“每次库存变化都通知”，还是“从正常区间进入低库存区间时通知一次”。处理器可以依据当前状态和告警状态决定是否发送；旧事件不能无条件覆盖新状态。</p><h2 id="dou-di-yu-xiu-fu" tabindex="-1">兜底与修复 <a class="header-anchor" href="#dou-di-yu-xiu-fu" aria-label="Permalink to &quot;兜底与修复&quot;">​</a></h2><p>Outbox 投递器要记录最老待发事件的年龄，消费者要记录积压和失败。兜底任务可以核对“已上传但没有对应版本转码结果的视频”，补建缺失动作。</p><p>修复时使用与正常流程相同的业务键和处理器，避免另一套绕过幂等与条件校验的写入路径。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>AWS Prescriptive Guidance：<a href="https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html" target="_blank" rel="noreferrer">Transactional outbox pattern</a></li><li>RabbitMQ：<a href="https://www.rabbitmq.com/docs/confirms" target="_blank" rel="noreferrer">Consumer Acknowledgements and Publisher Confirms</a></li></ul>',14))])}const g=n(c,[["render",h]]);export{_ as __pageData,g as default};
